DELETE FROM "airtable"."project_volunteers" as d WHERE EXISTS (SELECT 1 FROM "airtable_staging"."project_volunteers" as s WHERE d."id" = s."id")
INSERT INTO "airtable"."project_volunteers"("id", "created_time", "fields__join_id", "_dlt_load_id", "_dlt_id")                  SELECT "id", "created_time", "fields__join_id", "_dlt_load_id", "_dlt_id"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "id", "created_time", "fields__join_id", "_dlt_load_id", "_dlt_id"                         FROM "airtable_staging"."project_volunteers"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          